代码如下
```php
<?php

class MyServer {

    public $conf;
    public $server;

    public function __construct() {

    }


    /**
     * 设置配置
     * @param array $conf
     */
    public function setConf(array $conf) {
        $this->conf = $conf;

        return $this;
    }


    /**
     * 初始化服务
     * @return $this
     */
    public function initServer() {

        $this->server = new \swoole_http_server('0.0.0.0', 6666);
        $this->server->set($this->conf);

        return $this;
    }


    /**
     * 启动服务
     * @return $this
     */
    public function startServer() {
        $this->server->on('Start', [$this, 'onStart']);
        $this->server->on('WorkerStart', [$this, 'onWorkerStart']);
        $this->server->on('WorkerStop', [$this, 'onWorkerStop']);
        $this->server->on('WorkerError', [$this, 'onWorkerError']);
        $this->server->on('Connect', [$this, 'onConnect']);
        $this->server->on('Request', [$this, 'onRequest']);
        $this->server->on('Close', [$this, 'onClose']);
        $this->server->on('Task', [$this, 'onTask']);
        $this->server->on('Finish', [$this, 'onFinish']);

        echo("Service start success\r\n");
        $this->server->start();

        return $this;
    }


    /**
     * 当服务器启动时[事件]
     * @param object $serv swoole_server对象
     *
     * @return $this
     */
    public function onStart($serv) {
        echo "Master Start...\r\n";

        return $this;
    }


    /**
     * 当worker进程启动[事件]
     * @param object $serv swoole_server对象
     * @param int $workerId 从0-$worker_num之间的数字
     *
     * @return $this
     */
    public function onWorkerStart($serv, $workerId) {
        echo "Worker Start:[{$workerId}]...\r\n";

        if ($workerId == 1) {
            //启动定时器任务
            $timerId = swoole_timer_tick(100, function () use($serv) {
                echo "timer tick \r\n";
                $serv->task([]);
            });
        }

        return $this;
    }


    /**
     * 当worker进程停止[事件]
     * @param object $serv swoole_server对象
     * @param int $workerId 从0-$worker_num之间的数字
     *
     * @return $this
     */
    public function onWorkerStop($serv, $workerId) {
        echo "Worker Stop:[{$workerId}]...\r\n";

        return $this;
    }


    /**
     * 当worker进程发生异常时[事件]
     * @param $serv
     * @param $workerId
     * @param $workerPid
     * @param $exitCode
     *
     * @return $this
     */
    public function onWorkerError($serv, $workerId, $workerPid, $exitCode) {
        echo "on WorkerError...\r\n";
        echo "workerId[$workerId] workerPid[$workerPid] exitCode[$exitCode]\r\n";
        die;

        return $this;
    }


    /**
     * 当有新的连接进入时[事件]
     * @param object $serv swoole_server对象
     * @param mixed $fd 连接的文件描述符,发送数据/关闭连接时需要此参数
     * @param int $fromId 来自那个Reactor线程
     *
     * @return $this
     */
    public function onConnect($serv, $fd, $fromId) {
        echo "new Connect:[{$fromId}]...\r\n";

        return $this;
    }


    /**
     * 当有http请求时[事件]
     * @param object $request 请求对象
     * @param object $response 响应对象
     *
     * @return $this
     */
    public function onRequest($request, $response) {
        echo "on Request...\r\n";

        return $this;
    }



    /**
     * 当客户端连接关闭时[事件]
     * @param object $serv swoole_server对象
     * @param mixed $fd 连接的文件描述符,发送数据/关闭连接时需要此参数
     * @param int $fromId 来自那个Reactor线程
     *
     * @return $this
     */
    public function onClose($serv, $fd, $fromId) {
        echo "on Close:[{$fromId}]...\r\n";

        return $this;
    }


    /**
     * 当任务被调用时[事件]
     * @param object $serv swoole_server对象
     * @param int $taskId 任务ID
     * @param int $fromId 来自那个Reactor线程
     * @param array $taskData 任务数据
     *
     * @return $this
     */
    public function onTask($serv, $taskId, $fromId, $taskData) {
        echo "on Task...\r\n";

        return $this;
    }


    /**
     * 当任务完成时[事件]
     * @param object $serv swoole_server对象
     * @param int $taskId 任务ID
     * @param array $taskData 任务数据
     *
     * @return $this
     */
    public function onFinish($serv, $taskId, $taskData) {
        echo "on Finish...\r\n";

        return $this;
    }


}//end class


$conf = [
    //守护进程化
    'daemonize' => 0,
    //线程数,=CPU核数
    'reactor_num' => 2,
    //worker进程数,为CPU的1-4倍
    'worker_num' => 4,
    //worker进程的最大任务数
    'max_request' => 1024,
    //服务最大允许的连接数
    'max_conn' => 1024,
    //task进程的数量
    'task_worker_num' => 5,
    //task进程的最大任务数,0不限制
    'task_max_request' => 1024,
    //task的数据临时目录
    'task_tmpdir' => '/tmp',
    //数据包分发策略
    'dispatch_mode' => 2,
    //Listen队列长度
    'backlog' => 128,
    //指定swoole错误日志文件
    'log_file' => '/tmp/swoole.log',
    //日志级别
    'log_level' => 0,
    //启用心跳检测,每隔N秒轮循一次
    'heartbeat_check_interval' => 5,
    //表示连接最大允许空闲的时间,需要比heartbeat_check_interval大
    'heartbeat_idle_time' => 10,

    //打开包长检测
    'open_length_check' => true,
    //包长度值的类型
    'package_length_type' => 'N',
    //最大数据包尺寸
    'package_max_length' => 2097152, //2M
    'package_length_offset' => 0,
    'package_body_offset' => 4,
    //管道通信的内存缓存区长度
    'pipe_buffer_size' => 33554432, //32M
    //发送缓存区尺寸
    'buffer_output_size' => 3145728, //3M

    //立即发往客户端连接,提升响应速度
    'open_tcp_nodelay' => 1,
    //启用CPU亲和性设置
    'open_cpu_affinity' => 1,
    //设置端口重用
    'enable_reuse_port' => 1,
];
$service = new MyServer();
$service->setConf($conf)->initServer()->startServer();
```

